public sealed class RecordingSupplier : ISupplier
{
    private readonly bool _accepted;

    public RecordingSupplier(bool accepted)
    {
        _accepted = accepted;
    }

    public string Name => "Recording supplier";

    public List<string> OrderedSkus { get; } = new List<string>();

    public List<int> OrderedQuantities { get; } = new List<int>();

    public int CallCount => OrderedSkus.Count;

    public bool PlaceOrder(string sku, int quantity)
    {
        OrderedSkus.Add(sku);
        OrderedQuantities.Add(quantity);
        return _accepted;
    }
}

